1	/**
2	 * API Keys Router — handles API key CRUD, rate limits, and usage stats
3	 */
4	import { router } from "../_core/trpc";
5	import { governedProtectedProcedure, fullyGovernedMutationProcedure } from "../governance/trpc-enforcement";
6	import { z } from "zod";
7	import { TRPCError } from "@trpc/server";
8	import * as db from "../supabase-adapter";
9	
10	const protectedProcedure = governedProtectedProcedure;
11	// Security-sensitive mutations use full governance + structural integrity enforcement
12	const highStakesProcedure = fullyGovernedMutationProcedure;
13	
14	export const apiKeysRouter = router({
15	  list: protectedProcedure.query(async ({ ctx }) => {
16	    return db.getApiKeysByUserId(ctx.user!.id);
17	  }),
18	
19	  create: highStakesProcedure
20	    .input(z.object({
21	      name: z.string().min(1).max(100).optional(),
22	    }))
23	    .mutation(async ({ ctx, input }) => {
24	      // Per-plan API-key cap REMOVED (2026-07-06, owner request). It was blocking
25	      // key creation, and — because the subscriptions read is currently drifted
26	      // (getSubscriptionByUserId returns null → every user resolves to "free") —
27	      // it was capping ALL users at 1 key, not just free ones. Re-introduce
28	      // plan-based limits (free/pro/team/enterprise) once the billing/subscription
29	      // camelCase drift in supabase-db.ts is fixed and plans resolve correctly.
30	      return await db.createApiKey(ctx.user!.id, input.name);
31	    }),
32	
33	  regenerate: highStakesProcedure
34	    .input(z.object({ keyId: z.number() }))
35	    .mutation(async ({ ctx, input }) => {
36	      return db.regenerateApiKey(ctx.user!.id, input.keyId);
37	    }),
38	
39	  delete: protectedProcedure
40	    .input(z.object({ keyId: z.number() }))
41	    .mutation(async ({ ctx, input }) => {
42	      return db.deleteApiKey(ctx.user!.id, input.keyId);
43	    }),
44	
45	  keyUsage: protectedProcedure
46	    .input(z.object({
47	      keyPrefix: z.string(),
48	      days: z.number().min(1).max(90).default(30),
49	    }))
50	    .query(async ({ ctx, input }) => {
51	      const keys = await db.getApiKeysByUserId(ctx.user!.id);
52	      const key = keys.find((k: any) => k.keyPrefix === input.keyPrefix);
53	      if (!key) {
54	        throw new TRPCError({ code: 'NOT_FOUND', message: 'API key not found' });
55	      }
56	      return db.getUsageByApiKeyPrefix(input.keyPrefix, input.days);
57	    }),
58	
59	  updateRateLimit: protectedProcedure
60	    .input(z.object({
61	      keyId: z.number(),
62	      rateLimitOverride: z.number().nullable(),
63	    }))
64	    .mutation(async ({ ctx, input }) => {
65	      const keys = await db.getApiKeysByUserId(ctx.user!.id);
