/**
 * Supabase Adapter for Gravito
 * 
 * This adapter wraps supabase-db.ts functions to provide camelCase property names
 * that are compatible with the existing routers.ts code.
 */

import * as supabaseDb from './supabase-db';
import { generalLog } from './_core/logger';

// ============ Type Converters ============

function snakeToCamel(str: string): string {
  return str.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
}

function convertKeysToCamel<T extends Record<string, unknown>>(obj: T): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      result[snakeToCamel(key)] = obj[key];
    }
  }
  return result;
}

// ============ User Types (camelCase) ============

export interface User {
  id: number;
  openId: string;
  name: string | null;
  email: string | null;
  loginMethod: string | null;
  passwordHash: string | null;
  role: 'admin' | 'user';
  lastSignedIn: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface ApiKey {
  id: number;
  userId: number;
  keyHash: string;
  keyPrefix: string;
  name: string;
  isActive: boolean;
  lastUsedAt: string | null;
  createdAt: string;
}

export interface Subscription {
  id: number;
  userId: number;
  plan: string;
  stripeCustomerId: string | null;
  stripeSubscriptionId: string | null;
  status: string;
  currentPeriodStart: string | null;
  currentPeriodEnd: string | null;
  cancelAtPeriodEnd: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface ApiUsage {
  id: number;
  userId: number;
  apiKeyId: number | null;
  endpoint: string;
  callCount: number;
  date: string;
  createdAt: string;
}

export interface EmotionalHistory {
  id: number;
  userId: number;
  externalUserId: string | null;
  emotion: string;
  valence: number;
  arousal: number;
  escalationRisk: 'low' | 'medium' | 'high';
  context: string | null;
  conversationId: string | null;
  createdAt: string;
}

export interface EmotionalPattern {
  id: number;
  userId: number;
  externalUserId: string | null;
  patternType: 'recurring_frustration' | 'escalation_prone' | 'positive_engagement' | 'time_sensitive' | 'topic_triggered';
  description: string;
  triggers: string | null;
  frequency: number;
  lastOccurrence: string;
  recommendedApproach: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface BillingHistory {
  id: number;
  userId: number;
  stripeInvoiceId: string | null;
  stripePaymentIntentId: string | null;
  amount: number;
  currency: string;
  status: string;
  description: string | null;
  createdAt: string;
}

// ============ User Functions ============

export async function upsertUser(userData: {
  openId: string;
  name?: string | null;
  email?: string | null;
  loginMethod?: string | null;
  passwordHash?: string | null;
  role?: 'admin' | 'user';
  lastSignedIn?: Date;
}): Promise<void> {
  await supabaseDb.upsertUser(userData);
}

export async function getUserByOpenId(openId: string): Promise<User | null> {
  const user = await supabaseDb.getUserByOpenId(openId);
  if (!user) return null;
  return convertKeysToCamel(user as unknown as Record<string, unknown>) as unknown as User;
}

export async function getUserById(id: number): Promise<User | null> {
  const user = await supabaseDb.getUserById(id);
  if (!user) return null;
  return convertKeysToCamel(user as unknown as Record<string, unknown>) as unknown as User;
}

export async function getUserByEmail(email: string): Promise<User | null> {
  const user = await supabaseDb.getUserByEmail(email);
  if (!user) return null;
  return convertKeysToCamel(user as unknown as Record<string, unknown>) as unknown as User;
}

// ============ API Key Functions ============

export async function createApiKey(userId: number, name?: string): Promise<{ key: string; prefix: string }> {
  const result = await supabaseDb.createApiKey(userId, name);
  if (!result) {
    throw new Error('Failed to create API key');
  }
  return result;
}

export async function getApiKeysByUserId(userId: number): Promise<Partial<ApiKey>[]> {
  const keys = await supabaseDb.getApiKeysByUserId(userId);
  return keys.map(k => convertKeysToCamel(k as unknown as Record<string, unknown>)) as Partial<ApiKey>[];
}

export async function validateApiKey(key: string): Promise<ApiKey | null> {
  const apiKey = await supabaseDb.validateApiKey(key);
  if (!apiKey) return null;
  return convertKeysToCamel(apiKey as unknown as Record<string, unknown>) as unknown as ApiKey;
}

export async function deleteApiKey(userId: number, keyId: number): Promise<boolean> {
  return supabaseDb.deleteApiKey(userId, keyId);
}

export async function regenerateApiKey(userId: number, keyId: number): Promise<{ key: string; prefix: string } | null> {
  return supabaseDb.regenerateApiKey(userId, keyId);
}

// ============ Subscription Functions ============

export async function getSubscriptionByUserId(userId: number): Promise<Subscription | null> {
  const sub = await supabaseDb.getSubscriptionByUserId(userId);
  if (!sub) return null;
  return convertKeysToCamel(sub as unknown as Record<string, unknown>) as unknown as Subscription;
}

export async function createOrUpdateSubscription(subData: {
  userId: number;
  plan: string;
  stripeCustomerId?: string | null;
  stripeSubscriptionId?: string | null;
  status?: string;
  currentPeriodStart?: Date | null;
  currentPeriodEnd?: Date | null;
  cancelAtPeriodEnd?: boolean;
}): Promise<boolean> {
  return supabaseDb.createOrUpdateSubscription(subData);
}

// ============ Usage Functions ============

export async function recordApiUsage(userId: number, apiKeyId: number | null, endpoint: string): Promise<void> {
  return supabaseDb.recordApiUsage(userId, apiKeyId, endpoint);
}

export async function getUsageByUserId(userId: number, days: number = 30): Promise<ApiUsage[]> {
  const usage = await supabaseDb.getUsageByUserId(userId, days);
  return usage.map(u => convertKeysToCamel(u as unknown as Record<string, unknown>) as unknown as ApiUsage);
}

export async function getTotalUsageThisMonth(userId: number): Promise<number> {
  return supabaseDb.getTotalUsageThisMonth(userId);
}

export async function getUsageBreakdownByEndpoint(userId: number, days: number = 30) {
  const dbModule = await import('./db');
  return dbModule.getUsageBreakdownByEndpoint(userId, days);
}

// ============ Billing Functions ============

export async function getBillingHistory(userId: number): Promise<BillingHistory[]> {
  const history = await supabaseDb.getBillingHistory(userId);
  return history.map(h => convertKeysToCamel(h as unknown as Record<string, unknown>) as unknown as BillingHistory);
}

export async function recordBillingEvent(billingData: {
  userId: number;
  stripeInvoiceId?: string | null;
  stripePaymentIntentId?: string | null;
  amount: number;
  currency?: string;
  status: string;
  description?: string | null;
}): Promise<boolean> {
  return supabaseDb.addBillingRecord(billingData);
}

// ============ Rate Limiting ============

export async function checkRateLimit(
  userId: number,
  plan: string
): Promise<{ allowed: boolean; remaining: number; resetAt: Date }> {
  return supabaseDb.checkRateLimit(userId, plan);
}

// ============ Plan Limits (static, no DB needed) ============

const PLAN_LIMITS: Record<string, { calls: number; rate: number }> = {
  free: { calls: 100, rate: 10 },
  builder: { calls: 5000, rate: 50 },
  startup: { calls: 25000, rate: 100 },
  scale: { calls: 100000, rate: 250 },
  business: { calls: 500000, rate: 500 },
  enterprise: { calls: 2000000, rate: 1000 },
  enterprise_plus: { calls: 10000000, rate: 2500 },
};

export function getPlanLimit(plan: string): { calls: number; rate: number } {
  return PLAN_LIMITS[plan] || PLAN_LIMITS.free;
}

